interface ParsedOptions {
  devices: string[];
  from?: number;
  to?: number;
  /** 分日时区的规范名称;仅在 allowTz 时可由 --tz 指定。 */
  tz?: string;
}

/** 解析 --device/--from/--to(及 allowTz 时的 --tz)选项;出错返回错误消息字符串。 */
function parseOptions(rest: string[], allowTz = false): ParsedOptions | string {
  const devices: string[] = [];
  let from: number | undefined;
  let to: number | undefined;
  let tz: string | undefined;
  for (let i = 0; i < rest.length; i++) {
    let opt = rest[i];
    let value: string | undefined;
    const eq = opt.indexOf('=');
    if (opt.startsWith('--') && eq !== -1) {
      value = opt.slice(eq + 1);
      opt = opt.slice(0, eq);
    } else if (opt.startsWith('--')) {
      value = rest[i + 1];
      if (value === undefined) return `选项 '${opt}' 缺少值`;
      i++;
    } else {
      return `无法识别的参数 '${opt}'`;
    }
    if (opt === '--device') {
      if (value.trim() === '') return "'--device' 的值不能为空";
      devices.push(value);
    } else if (opt === '--from' || opt === '--to') {
      const ts = parseIso8601(value.trim());
      if (ts === null) {
        return `选项 '${opt}' 的时间无效: '${value}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`;
      }
      if (opt === '--from') from = ts;
      else to = ts;
    } else if (opt === '--tz' && allowTz) {
      const parsed = parseTimeZone(value);
      if (typeof parsed === 'string') return parsed;
      tz = parsed;
    } else {
      return `无法识别的选项 '${opt}'`;
    }
  }
  return { devices, from, to, tz };
}

/** 解析并校验 IANA 时区名称,返回规范名;无效返回错误消息字符串。 */
function parseTimeZone(raw: string): string | { tz: string } {
  const name = raw.trim();
  if (name === '') return "'--tz' 的值不能为空";
  if (!isValidTimeZone(name)) {
    return `未知时区: '${name}'(需运行环境支持的 IANA 时区名称,如 Asia/Shanghai、America/New_York)`;
  }
  return { tz: canonicalTimeZone(name) };
}

